VALUES (13415, 'tt0175122', NULL, 'Rikki-Tikki-Tavi', 'Rikki-Tikki-Tavi', 'movie', 1975, 'https://image.tmdb.org/t/p/w500/wbuqLHni4Wvwa41iIiRJNngrMac.jpg', 'https://image.tmdb.org/t/p/original/623ZnoUOYTADMvuVnq4o1CcNqyG.jpg', 'Rikki is a young mongoose who is adopted by a human family after nearly drowning in the river. He returns the favour by protecting them from two murderous cobra.', NULL, NULL, 1.5239, 6.6, 0, 9.01, '2026-10-18 12:45:15', '2026-10-18 12:45:15')
