VALUES (352490, 'tt4560008', NULL, 'This Beautiful Fantastic', 'This Beautiful Fantastic', 'movie', 2016, 'https://image.tmdb.org/t/p/w500/22b9jLGJ8OVzlEnWzqF0yRy5Na3.jpg', 'https://image.tmdb.org/t/p/original/eKGjQNJ6sbSB1LoIeNoGXG0HozV.jpg', 'Set against the backdrop of a beautiful garden in the heart of London, this contemporary fairy tale revolves around the unlikely friendship between a reclusive young woman and a cantankerous old widower. Bella Brown is a beautifully quirky young woman who dreams of writing and illustrating a successful children’s book. After she is forced by her landlord to deal with her neglected garden or face eviction, she meets her match, nemesis, and unlikely mentor in Alfie Stephenson, a grumpy, loveless, old man who lives next door who happens to be an amazing horticulturalist.', NULL, NULL, 1.862, 7.122, 0, 10.79, '2026-07-15 12:01:52', '2026-10-18 12:45:15')
