VALUES (18491, 'tt0169858', NULL, 'Neon Genesis Evangelion: The End of Evangelion', '新世紀エヴァンゲリオン劇場版 Air／まごころを、君に', 'movie', 1997, 'https://image.tmdb.org/t/p/w500/j6G24dqI4WgUtChhWjfnI4lnmiK.jpg', 'https://image.tmdb.org/t/p/original/AfyuI3glMCBDFmNPj9PY6DwbgGp.jpg', 'SEELE orders an all-out attack on NERV, aiming to destroy the Evas before Gendo can advance his own plans for the Human Instrumentality Project. Shinji is pushed to the limits of his sanity as he is forced to decide the fate of humanity.', NULL, NULL, 15.1468, 8.258, 0, 2.14929411764705875e+01, '2026-07-15 12:01:52', '2026-10-18 12:45:15')
