VALUES (3035, 'tt0021884', NULL, 'Frankenstein', 'Frankenstein', 'movie', 1931, 'https://image.tmdb.org/t/p/w500/mu6wHwH0IwCCaEYtpqujuPJYat1.jpg', 'https://image.tmdb.org/t/p/original/wFbPbJ9uRDpjY7micBTeolgkOA4.jpg', 'Henry Frankenstein pieces together body parts in the hope of bringing a human-like creature to life. The mad scientist’s dreams are shattered by his monstrous creation awakening with rage to a world that hates and fears him.', NULL, NULL, 4.1532, 7.463, 0, 12.6875, '2026-07-15 12:01:52', '2026-10-18 12:45:15')
