VALUES (10227, 'tt0062136', NULL, 'PlayTime', 'PlayTime', 'movie', 1967, 'https://image.tmdb.org/t/p/w500/kQOrS0DLUXYsqPMedM2G6NJcJBq.jpg', 'https://image.tmdb.org/t/p/original/pKX8G6IN8ZCRvKeHh6ctqoHZl0K.jpg', 'Clumsy Monsieur Hulot finds himself perplexed by the intimidating complexity of a gadget-filled Paris. He attempts to meet with a business contact but soon becomes lost. His roundabout journey parallels that of an American tourist, and as they weave through the inventive urban environment, they intermittently meet, developing an interest in one another. They eventually get together at a chaotic restaurant, along with several other quirky characters.', NULL, NULL, 3.7514, 7.7, 0, 2.87269565217391296e+01, '2026-07-15 12:01:52', '2026-10-18 12:45:15')
