VALUES (427, 'tt0050706', NULL, 'Mon Oncle', 'Mon oncle', 'movie', 1958, 'https://image.tmdb.org/t/p/w500/wH6RyPiXFy8INLbViVkchLVOmBc.jpg', 'https://image.tmdb.org/t/p/original/3yYNJeR6JynSE3Y1AfVIJQ6g3UX.jpg', 'Genial, bumbling Monsieur Hulot loves his top-floor apartment in a grimy corner of the city, and cannot fathom why his sister''s family has moved to the suburbs. Their house is an ultra-modern nightmare, which Hulot only visits for the sake of stealing away his rambunctious young nephew. Hulot''s sister, however, wants to win him over to her new way of life, and conspires to set him up with a wife and job.', NULL, NULL, 3.3236, 7.427, 0, 13.926, '2026-07-15 12:01:52', '2026-10-18 12:45:15')
