VALUES (4951, 'tt0147800', NULL, '10 Things I Hate About You', '10 Things I Hate About You', 'movie', 1999, 'https://image.tmdb.org/t/p/w500/ujERk3aKABXU3NDXOAxEQYTHe9A.jpg', 'https://image.tmdb.org/t/p/original/yvPbncYhMu9FfTjDhq0N5lgnVkO.jpg', 'On the first day at his new school, Cameron instantly falls for Bianca, the gorgeous girl of his dreams. The only problem is that Bianca is forbidden to date until her ill-tempered, completely un-dateable older sister Kat goes out, too. In an attempt to solve his problem, Cameron singles out the only guy who could possibly be a match for Kat: a mysterious bad boy with a nasty reputation of his own.', NULL, NULL, 15.6815, 7.597, 0, 3.15117391304347833e+01, '2026-07-20 01:02:04', '2026-10-18 12:45:15')
