VALUES (11861, 'tt0113347', NULL, 'How to Make an American Quilt', 'How to Make an American Quilt', 'movie', 1995, 'https://image.tmdb.org/t/p/w500/pI9UAemlWgdrnjRgYJsbTk8BSJc.jpg', 'https://image.tmdb.org/t/p/original/nOPCU3zmLTp1A6KpPtHTuAyzkf5.jpg', 'Soon-to-be-wed graduate student Finn Dodd develops cold feet when she suspects her fiancé is cheating on her. In order to clear her head, Finn visits her grandmother, Hy, and great aunt, Glady Joe Cleary, in Grasse, Calif. There, Finn learns that Hy and Glady Joe are members of a group of passionate quilters, and over the course of her visit she is regaled with tales of love and life by women who have collected rich experiences and much wisdom.', NULL, NULL, 2.6508, 6.385, 0, 11.875, '2026-07-20 01:02:04', '2026-10-18 12:45:15')
