VALUES (11529, 'tt0256415', NULL, 'Sweet Home Alabama', 'Sweet Home Alabama', 'movie', 2002, 'https://image.tmdb.org/t/p/w500/698cbxq0SRwCdOPG5Bwi7JDk12d.jpg', 'https://image.tmdb.org/t/p/original/xE0ouu4yVA4fBojdHg2UkfvRxY4.jpg', 'New York fashion designer Melanie Carmichael suddenly finds herself engaged to the city''s most eligible bachelor. But her past holds many secrets—including Jake, the redneck husband she married in high school, who refuses to divorce her. Bound and determined to end their contentious relationship once and for all, Melanie sneaks back home to Alabama to confront her past.', NULL, NULL, 7.1176, 6.426, 0, 17.386, '2026-07-29 20:51:09', '2026-10-18 12:45:15')
