VALUES (256961, 'tt3450650', NULL, 'Paul Blart: Mall Cop 2', 'Paul Blart: Mall Cop 2', 'movie', 2015, 'https://image.tmdb.org/t/p/w500/qML63w7vgspicwLK6xXGLK17cM0.jpg', 'https://image.tmdb.org/t/p/original/cVsmfmsuUWjM9EKhtmqxtPmQjQG.jpg', 'Security guard Paul Blart is headed to Las Vegas to attend a Security Guard Expo with his teenage daughter Maya before she departs for college. While at the convention, he inadvertently discovers a heist - and it''s up to Blart to apprehend the criminals.', NULL, NULL, 5.8486, 5.171, 0, 5.47621153846153845e+01, '2026-07-29 20:51:09', '2026-10-18 12:45:15')
