VALUES (65632, 'tt0059095', NULL, 'The 10th Victim', 'La decima vittima', 'movie', 1965, 'https://image.tmdb.org/t/p/w500/qwXXxwnN1yj5XiZBUrdazBRMqw1.jpg', 'https://image.tmdb.org/t/p/original/dCfusmm2ZeT2jnCd0biDAzIpSHx.jpg', 'In the near future, big wars are avoided by giving individuals with violent tendencies a chance to kill in the Big Hunt. The Hunt is the most popular form of entertainment in the world and also attracts participants who are looking for fame and fortune. It includes ten rounds for each competitor, five as the hunter and five as the victim.', NULL, NULL, 1.6862, 6.639, 0, 7.765, '2026-07-29 20:51:09', '2026-10-18 12:45:15')
