VALUES (28638, 'tt0142181', NULL, 'The Bird People in China', '中国の鳥人', 'movie', 1998, 'https://image.tmdb.org/t/p/w500/civu1OxSYyxywfEOeMyCZoAOt7H.jpg', 'https://image.tmdb.org/t/p/original/scfBpNaw7LZIV6NtDlC01HCjEpT.jpg', 'Wada, a salary man, is enlisted to venture off to China to investigate a potential Jade mine. After his arrival, Wada encounters a violent, yet sentimental, yakuza, who takes the liberty of joining his adventure through China. Led on their long and disastrous journey to the mine by Shen, the three men come across something even more magical and enticing.', NULL, NULL, 2.751, 7.2, 0, 8.71600000000000108e+00, '2026-07-30 18:28:39', '2026-10-18 12:45:15')
