VALUES (NULL, NULL, 1020, 'Grand Theft Auto V', 'Grand Theft Auto V', 'game', 2013, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2lbd.jpg', NULL, 'Grand Theft Auto V is a vast open world game set in Los Santos, a sprawling sun-soaked metropolis struggling to stay afloat in an era of economic uncertainty and cheap reality TV. The game blends storytelling and gameplay in new ways as players repeatedly jump in and out of the lives of the game’s three lead characters, playing all sides of the game’s interwoven story.', 'https://www.igdb.com/games/grand-theft-auto-v', '["Xbox Series X|S", "PlayStation 3", "PlayStation 4", "PC (Microsoft Windows)", "PlayStation 5", "Xbox 360", "Xbox One"]', NULL, NULL, 0, 6.01500000000000056e+00, '2026-07-30 18:28:39', '2026-10-18 12:45:15')
