VALUES (158852, 'tt1964418', NULL, 'Tomorrowland', 'Tomorrowland', 'movie', 2015, 'https://image.tmdb.org/t/p/w500/kziYpr5Nfw60P0My8aj1sgCEqed.jpg', 'https://image.tmdb.org/t/p/original/udYOmbW1JEZjVd726PWHlmptxPi.jpg', 'Bound by a shared destiny, a bright, optimistic teen bursting with scientific curiosity and a former boy-genius inventor jaded by disillusionment embark on a danger-filled mission to unearth the secrets of an enigmatic place somewhere in time and space that exists in their collective memory as "Tomorrowland."', NULL, NULL, 12.9899, 6.307, 0, 19.303125, '2026-07-31 03:33:23', '2026-10-18 12:45:15')
