VALUES (4806, 'tt0163187', NULL, 'Runaway Bride', 'Runaway Bride', 'movie', 1999, 'https://image.tmdb.org/t/p/w500/wzivR0yWJStVdhcl0A5rQvVdTQ7.jpg', 'https://image.tmdb.org/t/p/original/kvZxYVwy75O35YqvkHztYijFVRE.jpg', 'Having already left three grooms at the altar, Maggie Carpenter is branded "the runaway bride" by jaded New York journalist Ike Graham. But, after his facts are called into question, Ike races to Maggie''s hometown to save his reputation and report on her upcoming fourth trip down the aisle – during which he''s convinced she''ll run again. Though he''s there on a muckraking mission, Ike can''t help but fall for this breathtaking heartbreaker.', NULL, NULL, 12.3795, 6.1, 0, 6.51500000000000056e+00, '2026-08-08 02:23:49', '2026-10-18 12:45:15')
