VALUES (10950, 'tt0277027', NULL, 'I Am Sam', 'I Am Sam', 'movie', 2001, 'https://image.tmdb.org/t/p/w500/3MUXRSyx9gnA2lLSSTGLN8cQQ42.jpg', 'https://image.tmdb.org/t/p/original/mOsg2l9zq315ouw55rbNATSwgU1.jpg', 'Sam, a neurodivergent man, has a daughter with a homeless woman who abandons them when they leave the hospital, leaving Sam to raise Lucy on his own. But as Lucy grows up, Sam''s limitations as a parent start to become a problem and the authorities take her away. Sam convinces high-priced lawyer Rita to take his case pro bono and in turn teaches her the value of love and family.', NULL, NULL, 9.7456, 7.564, 0, 8.33599999999999852e+00, '2026-08-11 22:09:33', '2026-10-18 12:45:15')
