VALUES (326, 'tt0417148', NULL, 'Snakes on a Plane', 'Snakes on a Plane', 'movie', 2006, 'https://image.tmdb.org/t/p/w500/i0ynvZ89tV1t8MAL9FmeQELfXH0.jpg', 'https://image.tmdb.org/t/p/original/wxGhAD63EM7N2YIQw9bktgQR8QM.jpg', 'FBI agent Neville Flynn boards a flight from Honolulu, Hawaii to Los Angeles, escorting a key witness to testify against a mob boss at an upcoming trial. An on-board assassin releases a crate full of hundreds of deadly venomous snakes in an attempt to eliminate the witness. Flynn and a host of frightened passengers and crew must band together to survive the slithery threat.', NULL, NULL, 6.168, 5.483, 0, 8.02571428571428491e+00, '2026-08-11 22:09:33', '2026-10-18 12:45:15')
