VALUES (NULL, NULL, 19817, 'Scorn', 'Scorn', 'game', 2022, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co4v5c.jpg', NULL, 'Scorn is an atmospheric first person horror adventure game set in a nightmarish universe of odd forms and somber tapestry. It is designed around an idea of "being thrown into the world". Isolated and lost inside this dream-like world you will explore different interconnected regions in a non-linear fashion. The unsettling environment is a character itself. Every location contains its own theme (story), puzzles and characters that are integral in creating a cohesive lived in world. Throughout the game you will open up new areas, acquire different skill sets, weapons, various items and try to comprehend the sights presented to you.', 'https://www.igdb.com/games/scorn', '["Xbox Series X|S", "PC (Microsoft Windows)", "PlayStation 5"]', NULL, NULL, 0, 1.30100000000000015e+01, '2026-08-18 01:44:45', '2026-10-18 12:45:15')
